import numpy as np
from PIL import Image
for d in ['initial','closure','probe1','probe2']:
 p=f'/app/output/{d}/last/top.jpg'
 # closure images under flat 'last'
 im=np.array(Image.open(p))
 a=np.load(f'/app/output/{d}/depth_top.npy'); a=a[-1] if a.ndim==3 else a
 print('\n',d)
 # sample grid region x130:220 y90:155, list depth where pixels gray/darker than table, excluding white
 for y in range(90,156,5):
  vals=[]
  for x in range(130,221,5):
   rgb=im[y,x]; dep=float(a[y,x]);
   if dep<1.25 and (max(rgb)-min(rgb)<60 or min(rgb)<180): vals.append((x,round(dep,2),rgb.tolist()))
  if vals: print(y,vals)
