import sys, numpy as np
sys.path.insert(0,'/opt/tools'); from rcb_client import Robot
r=Robot(); s=r.spec(); obs=r.get_obs(cameras=['top'],include_depth=True); p=np.asarray(obs.meta['proprio']['now']); base=p[58:87].copy(); print('time',obs.meta['time_left_s'],'q',base[:7])
def gray(a): return np.mean(a.astype(float),axis=2)
img=gray(obs.last['top']); cy,cx=196,193; hy,hx=9,10; patch=img[cy-hy:cy+hy,cx-hx:cx+hx].copy(); patch-=patch.mean(); pn=np.linalg.norm(patch)+1e-9
T=np.array(obs.meta['cameras']['top']['cam2world_gl']); K=np.array(obs.meta['cameras']['top']['intrinsic_cv']); f=K[0,0]
def point(ob):
 g=gray(ob.last['top']); best=(-1,None,None)
 for v0 in range(max(0,cy-hy-30),min(g.shape[0]-2*hy,cy-hy+31)):
  for u0 in range(max(0,cx-hx-45),min(g.shape[1]-2*hx,cx-hx+46)):
   c=g[v0:v0+2*hy,u0:u0+2*hx]; c=c-c.mean(); score=float((c*patch).sum()/(pn*(np.linalg.norm(c)+1e-9)))
   if score>best[0]: best=(score,u0+hx,v0+hy)
 score,u,v=best; d=float(np.median(ob.depth['top'][0,v-3:v+4,u-3:u+4])); pc=np.array([(u-K[0,2])*d/f,(K[1,2]-v)*d/f,-d,1.]); return np.array([u,v,d,*((T@pc)[:3])]),score
print('base',point(obs))
for j in range(7):
 a=base.copy(); a[j]+=.035; out=r.submit('joint_position',a,dt=.45,cameras=['top'],include_depth=True); z,sc=point(out); print(j,z.tolist(),round(sc,3))
